import type { MetadataRoute } from "next";

/**
 * Web app manifest — generated by the App Router (Next 16 file convention).
 * Colors come from the StoryKeep palette in src/app/globals.css:
 *   page bg   oklch(0.965 0.018 88) -> #f8f3e6
 *   primary   oklch(0.52 0.13 42)  -> #a54a24 (terracotta)
 * Icons are generated by scripts/generate_pwa_icons.py.
 */

// Next 16 requires explicit static config on metadata routes under
// `output: export` (static export) — the manifest is build-time constant.
export const dynamic = "force-static";

export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "StoryKeep",
    short_name: "StoryKeep",
    description: "A personal RSS reader and lifelong article archive.",
    start_url: "/",
    scope: "/",
    display: "standalone",
    orientation: "any",
    background_color: "#f8f3e6",
    theme_color: "#a54a24",
    categories: ["productivity", "news", "books"],
    icons: [
      {
        src: "/icons/icon-192.png",
        sizes: "192x192",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/icons/icon-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/icons/icon-maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
  };
}
